\begin{ex}%[9H5C1-5]
Cho đường tròn ${(O; 7cm)}$. Gọi ${AB}$ và ${CD}$ là hai đường kính có vị trí thay đổi. Diện tích lớn nhất của tứ giác ${ACBD}$ là 
\choice
{ ${49}cm^{2}$   }
   {  ${50}cm^{2}$  }
     { \True ${98}cm^{2}$  }
    { ${97}cm^{2}$   }
\loigiai{
\begin{tikzpicture}
    % Vẽ lưới để hỗ trợ vẽ


    % Vẽ đường tròn tâm O
    \draw[thick] (0,0) circle(3);

    % Tâm O
    \node at (0,0) [circle,fill,inner sep=1.5pt, label=above right:{$O$}] {};

    % Tọa độ các điểm của hình chữ nhật nội tiếp
    \coordinate (A) at (2.54,1.59);
    \coordinate (D) at (-2.54,1.59);
    \coordinate (C) at (2.54,-1.59);
    \coordinate (B) at (-2.54,-1.59);

    % Vẽ các điểm A, B, C, D
    \foreach \p/\pos in {A/right, B/left, C/right, D/left}
    \node at (\p) [circle,fill,inner sep=1.5pt, label=\pos:{$\p$}] {};

    % Vẽ hình chữ nhật ACBD
    \draw[thick] (A) -- (D) -- (B) -- (C) -- (A)--cycle;
    \draw[thick] (A) -- (B);
        \draw[thick] (D) -- (C);
    % Xác định và vẽ điểm H trên AB sao cho CH vuông góc với AB
    \coordinate (H) at (1.11,0.69); % Điểm H trên đoạn AB
    \draw[thick] (C) -- (H);
            \path
    (H) pic[draw=black,fill=white!25, angle radius = 5] {right angle = C--H--A};
    % Vẽ điểm H
    \node at (H) [circle,fill,inner sep=1.5pt, label=above:{$H$}] {};

\end{tikzpicture}
Ta có $\widehat{ACB} =\widehat {ADB} = \widehat {DBC} =90^{\circ}$ nên ${ACBD}$ là hình chữ nhật\\
${S_{ACBD} } = 2{S_{ACB} }$ Kẻ $CH \bot AB $ tại ${H}$\\
Ta có ${S_{ACB}}= \dfrac{1}{2}.AB.CH \le AB.CO =\dfrac{1}{2}.14.7= 49 cm^{2}$\\
${S_{ACBD} } \le 98cm^{2}$\\
Dấu “=” xảy ra khi $H \equiv O$  hay $CD \bot AB $, khi này hình chữ nhật ${ACBD}$ trở thành hình vuông.\\
Vậy giá trị lớn nhất của ${S_{ACBD} }=98cm^{2}$
}\end{ex}

